13	// PERS-007 against ECON-001's IDLE_QUEUES, the cohort reading that failed (live: player 37 played
14	// this hour with 2 of 2 planets buildable and idle). "Buildable" is the cohort's word for a planet
15	// QueueableBuildingPlanner::steps() offers a step for, so the planner and the account must agree:
16	// a planet whose pile the goal reserves is being saved for, not neglected, and must not be offered.
17	// Offered while the account rightly saves is the defect -- the read-out then calls a saver idle.
18	test('a goal saver holding its pile is offered no step, so its planets never read buildable', function (): void {
19	    $situation = Situation::of($this)->goalSaver()->colony()
20	        ->levelEveryPlanet('metal_mine', 13)
21	        ->levelEveryPlanet('crystal_mine', 13)
22	        ->levelEveryPlanet('deuterium_synthesizer', 13)
23	        ->levelEveryPlanet('solar_plant', 30)
24	        ->levelEveryPlanet('metal_store', 20)
25	        ->levelEveryPlanet('crystal_store', 20)
26	        ->levelEveryPlanet('deuterium_store', 20)
27	        ->stockEveryPlanet(5_000, 2_000, 1_000);
28	
29	    $situation->session();
30	
31	    $planned = collect(app(QueueableBuildingPlanner::class)->steps($this->currentUserId))->pluck('planetId')->unique();
32	
33	    expect($planned->all())->toBe([], 'expected the goal-saver planets not to read as buildable, but ' . $situation->account());
34	});
35	
36	// The other half of the same reading: a session that also ferries stock between the account's own
37	// planets must still leave each planet the step the planner offers for it. A ferry that empties a
38	// planet before its building is placed spends the queue slot and the step goes with it.
39	test('a goal saver that ferries stock still queues the step it was saving for', function (): void {
40	    $situation = Situation::of($this)->goalSaver()->colony()
41	        ->levelEveryPlanet('metal_mine', 13)
42	        ->levelEveryPlanet('crystal_mine', 13)
43	        ->levelEveryPlanet('deuterium_synthesizer', 13)
44	        ->levelEveryPlanet('solar_plant', 30)
45	        ->levelEveryPlanet('metal_store', 20)
46	        ->levelEveryPlanet('crystal_store', 20)
47	        ->levelEveryPlanet('deuterium_store', 20)
48	        ->stockEveryPlanet(500_000, 300_000, 100_000)
49	        ->ships('small_cargo', 5);
50	
51	    $situation->session();
52	
53	    $planets = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)->pluck('id');
54	    $planned = collect(app(QueueableBuildingPlanner::class)->steps($this->currentUserId))->pluck('planetId')->unique();
55	    $busy = BuildingQueue::query()->whereIn('planet_id', $planets)->where('processed', 0)->distinct()->pluck('planet_id');
56	
57	    expect($planned->diff($busy)->values()->all())->toBe([], $situation->account());
58	});

