 3	use Modules\AI\Tests\Support\Situation;
 4	use Tests\IsolatedAccountTestCase;
 5	
 6	require_once __DIR__ . '/../../Support/Situation.php';
 7	
 8	uses(IsolatedAccountTestCase::class);
 9	
10	/**
11	 * Every planet the account owns mines deep enough that the next level is out of reach of its stock,
12	 * with the energy and storage that keep the earlier passes out of the way: the whole account is saving.
13	 */
14	function savingsGoalPlanet(Situation $situation): Situation
15	{
16	    return $situation
17	        ->levelEveryPlanet('metal_mine', 13)
18	        ->levelEveryPlanet('crystal_mine', 13)
19	        ->levelEveryPlanet('deuterium_synthesizer', 13)
20	        ->levelEveryPlanet('solar_plant', 30)
21	        ->levelEveryPlanet('metal_store', 20)
22	        ->levelEveryPlanet('crystal_store', 20)
23	        ->levelEveryPlanet('deuterium_store', 20)
24	        ->stockEveryPlanet(5_000, 2_000, 1_000);
25	}
26	
27	// PERS-007: a goal saver names the step it is saving for -- here the next mine, out of reach of the
28	// 5.000 metal it holds -- and keeps the pile against it, so a cheaper facility that is affordable
29	// waits instead of eating what the goal needs.
30	test('a goal saver short of its goal holds the pile instead of buying a cheaper step', function (): void {
31	    $situation = savingsGoalPlanet(Situation::of($this)->goalSaver())->session();
32	
33	    expect($situation->queued())->toBeEmpty('expected the goal saver to hold its pile, but ' . $situation->account());
34	});
35	
36	// The same balance without the strategy is the spender the decision doctrine describes: it buys the
37	// step it can pay for. The strategy decides how the pile is spent, never whether it is spent.
38	test('an account with no saving strategy buys the affordable step with the same balance', function (): void {
39	    savingsGoalPlanet(Situation::of($this))->session()->expectBuildingQueueBusy();
40	});
41	
42	// The reserve is not a freeze: once the pile reaches the goal, the goal is bought and the account
43	// spends again, so a goal saver is never left idle by its own saving.
44	test('a goal saver whose pile reaches the goal buys it', function (): void {
45	    savingsGoalPlanet(Situation::of($this)->goalSaver())
46	        ->resources(1_000_000, 1_000_000, 1_000_000)
47	        ->session()
48	        ->expectBuildingQueueBusy();
49	});
50	
51	// With nothing to save for -- every step the planner offers is affordable at a glance -- the goal
52	// saver spends like anyone else.
53	test('a funded goal saver with nothing to save for still queues a building', function (): void {
54	    Situation::of($this)->goalSaver()->resources(1_000_000, 1_000_000, 1_000_000)->session()->expectBuildingQueueBusy();
55	});

