   40	/**
   41	 * Turns a session's selected intent into the one work item that carries it out.
   42	 *
   43	 * Recording the decision and acting on it stay separate steps: the decision is traceable whether or
   44	 * not the host would allow it, and only an intent with a real executor becomes work. An intent
   45	 * without one stays in the trace rather than becoming a work item that quietly does nothing.
   46	 */
   47	class ScheduleAiIntentAction
   48	{
   49	    private const PAYLOAD_PLANET_ID = 'planet_id';
   50	
   51	    private const PAYLOAD_BUILDING_ID = 'building_id';
   52	
   53	    private const PAYLOAD_RESEARCH_ID = 'research_id';
   54	
   55	    private const PAYLOAD_UNIT_ID = 'unit_id';
   56	
