   72	
   73	    private const PAYLOAD_TARGET_GALAXY = 'target_galaxy';
   74	
   75	    private const PAYLOAD_TARGET_SYSTEM = 'target_system';
   76	
   77	    private const PAYLOAD_TARGET_POSITION = 'target_position';
   78	
   79	    private const PAYLOAD_TARGET_TYPE = 'target_type';
   80	
   81	    private const PAYLOAD_PROBE_COUNT = 'probe_count';
   82	
   83	    private const PAYLOAD_SOURCE_PLANET_ID = 'source_planet_id';
   84	
   85	    private const PAYLOAD_TARGET_PLANET_ID = 'target_planet_id';
   86	
   87	    private const PAYLOAD_METAL = 'metal';
   88	
   89	    private const PAYLOAD_CRYSTAL = 'crystal';
   90	
   91	    private const PAYLOAD_DEUTERIUM = 'deuterium';
   92	
   93	    private const PAYLOAD_REASON = 'reason';
   94	
   95	    private const PAYLOAD_SPEED = 'speed';
   96	
   97	    private const PAYLOAD_JUMP_GATE_PLANET_ID = 'jump_gate_planet_id';
   98	
   99	    private const PAYLOAD_PERCENTAGE = 'percentage';
  100	
  101	    /**
  102	     * The gap between one planet's order and the next in a login, the way a player clicks through
  103	     * planets. It also keeps a session's intents from reaching the workers in the same instant, where
  104	     * all but one lose the per-player lock and wait out a retry.
  105	     */
  106	    private const SECONDS_BETWEEN_PLANETS = 20;
  107	
  108	    public function __construct(
  109	        private QueueableBuildingPlanner $queueableBuildingPlanner,
  110	        private QueueableUnitPlanner $queueableUnitPlanner,
  111	        private QueueableColonyPlanner $queueableColonyPlanner,
  112	        private QueueableExpeditionPlanner $queueableExpeditionPlanner,
  113	        private QueueableFleetSavePlanner $queueableFleetSavePlanner,
  114	        private QueueableSpyPlanner $queueableSpyPlanner,
  115	        private QueueableTransferPlanner $queueableTransferPlanner,
  116	        private QueueableRecyclePlanner $queueableRecyclePlanner,
  117	        private QueueableMinePercentPlanner $queueableMinePercentPlanner,
  118	        private QueueablePhalanxPlanner $queueablePhalanxPlanner,
  119	        private RaidPlanner $raidPlanner,
  120	        private SaveFailurePolicy $saveFailurePolicy,
  121	        private AiClock $clock,
  122	    ) {
  123	    }
  124	
  125	    /**
  126	     * Writes the one work item that carries the intent out, keyed by the session's
  127	     * own id: a retried session converges on one action, a later session decides
  128	     * again. The payload is whatever the plan approved, so the schedule and the
  129	     * executor always name the same objective.
  130	     *
  131	     * @param array<string, mixed> $payload
  132	     */
  133	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
  134	    {
  135	        AiWorkItem::query()->firstOrCreate(
  136	            ['idempotency_key' => 'intent:session:' . $sessionWorkItem->id . $keySuffix],
  137	            [
  138	                'player_id' => $profile->player_id,
  139	                'kind' => $kind,
  140	                'due_at' => $dueAt ?? $this->clock->now(),
  141	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
  142	                'state' => AiWorkState::Pending,
  143	                'payload' => $payload,
  144	            ],
  145	        );
  146	    }
  147	
  148	    public function handle(AiProfile $profile, AiWorkItem $sessionWorkItem, DecisionTrace $trace): void
  149	    {
  150	        // Every case is listed: adding a capability means deciding here where it is executed, and
  151	        // a capability with no executor must not be published to begin with.
  152	        $type = $trace->selected->candidate->type;
  153	        // The unit plan is read here, before the building steps are enqueued, because one order's
  154	        // placement decides whether it happens at all: the first wall of a planet that stands bare
  155	        // beside a walled sibling is priced against the balance those steps spend, so the host
  156	        // refuses it and the planet stays naked session after session (QUAL-003).
  157	        //
  158	        // It is read for every chosen action, not only QueueUnits: the wall candidate is one of a
  159	        // dozen and the economy's habit outranks it in most logins, so waiting for the sessions the
  160	        // engine happens to pick the shipyard left the bare planet naked while the account kept
  161	        // colonising (measured live 2 Oct 2026: 1 planet at zero defence beside a sibling holding
  162	        // 1,746). A login is one wall order whichever action was chosen.
  163	        // The wall's own facility may be refused by the economy in the same login (the planet is saving
  164	        // for its next mine), so the unit plan is asked before the building steps for every chosen
  165	        // action: a bare planet's wall is the one order whose placement decides whether it happens.
  166	        $units = $this->queueableUnitPlanner->plan($profile->player_id);
  167	        $unitsFirst = $units instanceof QueueableUnit && $units->aheadOfEconomy;
  168	
  169	        // The marked wall is written before the building steps, because work falls due in the order
  170	        // it was written and same-instant work keeps that order: written after them, the steps have
  171	        // already spent the balance the wall was priced against, the host refuses it, and the planet
  172	        // stands naked beside its walled sibling again on the next login (QUAL-003).
  173	        //
  174	        // A wall placed on a login that chose something else keeps a key of its own, so the session's
  175	        // own action still owns the primary key: a retried session converges on that action, and the
  176	        // wall is one more order in the login rather than the login's objective.
  177	        if ($unitsFirst) {
  178	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now(), $units, $type === AiCandidateActionType::QueueUnits ? '' : ':wall');
  179	        }
  180	
  181	        // Every *other* bare sibling takes its wall in the same login: a player clicks through all the
