 10	class DecisionEngine
 11	{
 12	    public function __construct(
 13	        private CandidateActionFactory $candidateActionFactory,
 14	        private UtilityScorer $utilityScorer,
 15	        private RandomSource $randomSource,
 16	    ) {
 17	    }
 18	
 19	    public function decide(AiProfile $profile, PerceptionSnapshot $perception, string $decisionKey): DecisionTrace
 20	    {
 21	        $generation = $this->candidateActionFactory->create($perception);
 22	        $scored = $this->utilityScorer->score($profile, $generation, $decisionKey);
 23	        $selected = $this->situationalErrand(
 24	            $scored,
 25	            $this->utilityScorer->select($profile, $scored, $decisionKey),
 26	        );
 27	        $selected = $this->idleOverride(
 28	            $profile,
 29	            $perception,
 30	            $scored,
 31	            $selected,
 32	            $decisionKey,
 33	        );
 34	        $inputHash = hash('sha256', json_encode($perception->traceInput(), JSON_THROW_ON_ERROR));
 35	
 36	        return app()->makeWith(DecisionTrace::class, [
 37	            'perception' => $perception,
 38	            'candidates' => $scored,
 39	            'selected' => $selected,
 40	            'rejections' => $generation->rejections,
 41	            'inputHash' => $inputHash,
 42	        ]);
 43	    }
 44	
 45	    /**
 46	     * A login's one errand. ScheduleAiIntentAction refills the build queues and the lab in every
 47	     * session whatever wins the slot, so a chore that fills them anyway spends the errand on work
 48	     * that was going to happen — and the fleet errand the situation actually offers (a raid from a
 49	     * report, debris at home, a colony ship, an expedition) never gets picked. The best candidate
 50	     * that is neither a queue chore nor doing nothing takes the slot, unless doing nothing scores
 51	     * higher: a quiet login is still a legitimate choice, so the floor for taking the slot is
 52	     * DoNothing's own score rather than zero. When no errand is offered at all the chore keeps the
 53	     * slot, which is what an account with only an economy to tend does.
 54	     *
 55	     * @param array<int, ScoredCandidate> $scored the whole ranked list, best first
 56	     */
 57	    private function situationalErrand(array $scored, ScoredCandidate $selected): ScoredCandidate
 58	    {
 59	        // ARB-001: the errand slot is spent on what the situation offers, not on the chore that
 60	        // fills itself.
 61	        if (!in_array($scored[0]->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research], true)) {
 62	            return $selected;
 63	        }
 64	
 65	        $doNothing = null;
 66	        foreach ($scored as $candidate) {
 67	            if ($candidate->candidate->type === AiCandidateActionType::DoNothing) {
 68	                $doNothing = $candidate;
 69	                break;
 70	            }
 71	        }
 72	
 73	        if ($doNothing === null) {
 74	            return $selected;
 75	        }
 76	
 77	        // $scored is already ranked best first, so the first candidate past the chores is the best
 78	        // remaining one: if it cannot beat doing nothing, neither can anything ranked below it.
 79	        foreach ($scored as $candidate) {
 80	            if (in_array($candidate->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research, AiCandidateActionType::DoNothing], true)) {
 81	                continue;
 82	            }
 83	
 84	            return $candidate->score > $doNothing->score ? $candidate : $selected;
 85	        }
 86	
 87	        return $selected;
 88	    }
 89	
 90	    /**
 91	     * The rare "opened the game, did nothing, closed it" moment: a small seeded,
 92	     * skill-band-aware draw that picks DoNothing even when a real action won.
 93	     * A save or a reaction wake always wins — variance never trades away a real
 94	     * reaction (V2/V6 safety).
 95	     *
 96	     * @param array<int, ScoredCandidate> $scored
 97	     */
 98	    private function idleOverride(AiProfile $profile, PerceptionSnapshot $perception, array $scored, ScoredCandidate $selected, string $decisionKey): ScoredCandidate
 99	    {
100	        if ($perception->fleetsaveEligible || $perception->reactionWakeAt !== null) {
101	            return $selected;
102	        }
103	
104	        if ($selected->candidate->type === AiCandidateActionType::DoNothing) {
105	            return $selected;
106	        }
107	
108	        if ($this->randomSource->unitInterval($profile->random_seed, $decisionKey . ':idle') >= $profile->skill_band->idleOverrideProbability()) {
109	            return $selected;
110	        }
111	
112	        foreach ($scored as $candidate) {
113	            if ($candidate->candidate->type === AiCandidateActionType::DoNothing) {
114	                return $candidate;
115	            }
116	        }
117	
118	        return $selected;
119	    }
120	}

