43	            }
44	            if ($player->isInVacationMode()) {
45	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
46	            }
47	
48	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
49	            $building = ObjectService::getObjectById($buildingId);
50	            if ($building->type !== GameObjectType::Building && $building->type !== GameObjectType::Station) {
51	                return AiActionResult::rejected(AiQueueActionReason::NotABuilding);
52	            }
53	            // The host's own predicate: the two unit-producing stations cannot be upgraded while
54	            // ships or defence are in production. The module names no object here.
55	            if ($player->isObjectUpgradeBlocked($buildingId)) {
56	                return AiActionResult::rejected(AiQueueActionReason::ShipyardBusy);
