  321	 * Why a planet that nothing could be queued on is not building: the refusal of its first candidate,
  322	 * asked of the planner's own gates. A technology among the candidates means the lab is taken.
  323	 */
  324	function saturation_reason(QueueableBuildingPlanner $planner, AiProfile $profile, PlanetService $planet): string
  325	{
  326	    foreach ($planner->passes($profile) as $candidates) {
  327	        foreach ($candidates($planet) as $candidate) {
  328	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
  329	                return 'lab busy';
  330	            }
  331	
  332	            return $planner->refusal($planet, $candidate) ?? 'queueable';
  333	        }
  334	    }
  335	
  336	    return 'no candidate';
  337	}
